// Generated by pnpm new. A per-sketch copy: edit freely for this sketch only (docs/spec/publish-pipeline.md).
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { defineConfig, type Plugin } from 'vite';

// Dev only. The debug pane POSTs the current knob values here and this writes params.json (debug.ts, params.ts).
// apply: 'serve' keeps the endpoint out of the build, and the write is a source change, so Vite reloads the page.
const saveParams: Plugin = {
  name: 'save-params',
  apply: 'serve',
  configureServer(server) {
    server.middlewares.use('/__params', (req, res, next) => {
      if (req.method !== 'POST') return next();
      let body = '';
      req.on('data', (chunk) => (body += chunk));
      req.on('end', () => {
        try {
          const values: unknown = JSON.parse(body);
          // A bad write would leave the sketch failing at load (params.ts throws) until the file is fixed by hand.
          const ok =
            typeof values === 'object' &&
            values !== null &&
            !Array.isArray(values) &&
            Object.values(values).every((v) => typeof v === 'number' && Number.isFinite(v));
          if (!ok) throw new Error('expected a flat object of finite numbers');
          writeFileSync(join(import.meta.dirname, 'params.json'), JSON.stringify(values, null, 2) + '\n');
          res.end('ok');
        } catch (error) {
          res.statusCode = 400;
          res.end(String(error));
        }
      });
    });
  },
};

// Property mangling renames every unquoted property. OFF by default (decision 0008): it has no case where
// it is both worth it and safe. A sketch that bundles no library saves almost nothing (your own code is a
// few KB); a sketch that bundles one saves ~13 KB gzipped, but every byte of that comes from renaming the
// library's internals -- which is exactly what breaks (three looks up ShaderChunk / ShaderLib / shaderIDs by
// strings taken from shader source and material types, and mangling renames only the keys).
//
// Turning it on also brings back a rule for the whole sketch: every property referenced by string (uniform
// names, Tweakpane bindings, JSON keys) must be quoted -- { 'speed': 1 } -- and breakage shows up only in
// the build output, never in dev. Leave it off unless this sketch is large hand-written code with no
// library in the bundle. `artifacts run` (harness check) opens the real build and will catch it either way.
const mangleProperties = false;

export default defineConfig({
  root: import.meta.dirname,
  plugins: [saveParams],
  // Emit imported JSON as JSON.parse('...'), so property mangling (if ever turned on) cannot rename a knob.
  json: { stringify: true },
  // Relative base so the build output can be moved (decision 0004). Do not write absolute paths in sketch code.
  base: './',
  build: {
    // Output straight into public/lab/<slug>/ (committed; served by Pages as-is. decision 0001).
    outDir: '../../public/lab/wip',
    emptyOutDir: true,
    target: 'esnext',
    // Sketches are a single chunk; the modulepreload polyfill is dead weight.
    modulePreload: { polyfill: false },
    minify: 'terser',
    terserOptions: {
      mangle: {
        toplevel: true,
        ...(mangleProperties ? { properties: { keep_quoted: true } } : {}),
      },
      compress: {
        passes: 1,
        arguments: true,
        // OFF: it rewrites true/false as 1/0, which libraries do not survive -- three's HDRLoader (2026-10-13) and
        // Tweakpane's getContext({ willReadFrequently: true }) (2026-10-17) both broke only in the build
        // (docs/learnings.md). A few bytes are not worth a sketch that dies at load.
        booleans_as_integers: false,
        // Only log / info / debug. console.error and console.warn stay: they are how three reports a shader or
        // pipeline that failed to compile, and `artifacts run` fails on console.error. With drop_console: true the
        // build broke in silence (2026-10-17, decision 0008).
        drop_console: ['log', 'info', 'debug'],
        drop_debugger: true,
        keep_fargs: false,
        module: true,
        pure_getters: true,
        unsafe: true,
        unsafe_math: true,
        unsafe_methods: true,
        unsafe_proto: true,
        unsafe_undefined: true,
      },
    },
  },
});
